public class Rectangle {
    private double width;
    private double height;

    public Rectangle(double width, double height) {
        if (width <= 0 || height <= 0) {
            throw new IllegalArgumentException("width and height must be positive");
        }
        this.width = width;
        this.height = height;
    }

    public Rectangle(double side) {
        this(side, side);   // a square is just a rectangle with equal sides
    }

    public double area() {
        return width * height;
    }
}

Rectangle square = new Rectangle(4.0);
System.out.println(square.area());   // 16.0

Rectangle bad = new Rectangle(-2.0);   // throws IllegalArgumentException, from the SAME validation

import java.util.ArrayList;
import java.util.List;

public class Team {
    private List<String> members = new ArrayList<>();

    public void addMember(String name) {
        members.add(name);
    }

    public List<String> getMembers() {
        return new ArrayList<>(members);   // defensive copy -- callers can't mutate the original
    }
}

Team team = new Team();
team.addMember("Amy");

List<String> snapshot = team.getMembers();
snapshot.add("Zoe");                 // mutates the COPY only

System.out.println(team.getMembers());   // [Amy] -- Zoe never actually joined the real team

