Employee e = new SalesEmployee("Dana", 40000.0, 20000.0);
System.out.println(e.totalPay());   // 41000.0

interface Chargeable {
    double calculateCharge();
}

interface Refundable {
    double refundAmount();
}

class Order implements Chargeable, Refundable {
    private double total;
    private boolean cancelled;

    public Order(double total) {
        this.total = total;
    }

    public void cancel() {
        cancelled = true;
    }

    @Override
    public double calculateCharge() {
        return cancelled ? 0.0 : total;
    }

    @Override
    public double refundAmount() {
        return cancelled ? total : 0.0;
    }
}

Order order = new Order(150.0);
order.cancel();
System.out.println(order.calculateCharge());   // 0.0
System.out.println(order.refundAmount());      // 150.0

interface Logger {
    void log(String message);

    default void logError(String message) {
        log("ERROR: " + message);
    }
}

class ConsoleLogger implements Logger {
    @Override
    public void log(String message) {
        System.out.println(message);
    }
    // logError is not implemented here -- it uses the interface's default
}

Logger logger = new ConsoleLogger();
logger.log("starting up");
logger.logError("disk full");
// prints:
// starting up
// ERROR: disk full

