interface Payable {
    double calculatePay();
}

abstract class Worker implements Payable {
    protected String name;

    public Worker(String name) {
        this.name = name;
    }
}

class Contractor extends Worker {
    private double hourlyRate;
    private int hoursWorked;

    public Contractor(String name, double hourlyRate, int hoursWorked) {
        super(name);
        this.hourlyRate = hourlyRate;
        this.hoursWorked = hoursWorked;
    }

    @Override
    public double calculatePay() {
        return hourlyRate * hoursWorked;
    }
}

public class Main {
    public static void main(String[] args) {
        Worker w = new Contractor("Sam", 50.0, 10);
        System.out.println(w.calculatePay());   // 500.0
    }
}
